# Architecture-bearing files include source, IDL/schema, and configuration
# files.  Structural ownership checks intentionally apply to a narrower set:
# metadata and documentation are inventoried, but they are not authored source
# units merely because their suffix is supported by the file walker.
SOURCE_BEARING_IDL_EXTENSIONS = {".avsc", ".capnp", ".fbs", ".gql", ".graphql", ".proto", ".sql", ".thrift"}
SOURCE_BEARING_CONFIG_EXTENSIONS = {".cfg", ".conf", ".ini", ".json", ".jsonc", ".toml", ".xml", ".yaml", ".yml"}
