GENERIC_FILENAMES = GENERIC_BUCKETS | {"constants", "factory", "functions", "stuff"}
# A suffix that describes a procedural category rather than a durable
# capability is still a review finding when attached to an owned stem.  Keep
# this set deliberately narrow: domain words such as ``runtime`` or
# ``contract`` are semantic and must not be silently reclassified.
GENERIC_PROCEDURAL_SUFFIXES = {
    "base", "commit", "common", "commons", "constants", "factory", "factories",
    "functions", "helper", "helpers", "impl", "manager", "managers", "misc",
    "model", "models", "open", "reduce", "stuff", "type", "types", "util",
    "utils", "validation", "validations", "validator", "validators",
}
PROCEDURAL_PHASES = {"commit", "open", "reduce"}
STRUCTURAL_DIRECTORIES = {"app", "apps", "bin", "cmd", "config", "docs", "examples", "include", "lib", "libs", "main", "pkg", "script", "scripts", "src", "source", "test", "tests", "tool", "tools"}
TEMPORAL_OR_NUMBERED = re.compile(r"(?:^|[-_.])(new|old|final|latest|backup|copy|extra|temp|tmp|v\d+|\d+)(?:[-_.]|$)", re.IGNORECASE)
CATEGORY_CHAIN = re.compile(r"(?:base|controller|factory|handler|helper|impl|manager|provider|repository|service|util)(?:[-_](?:base|controller|factory|handler|helper|impl|manager|provider|repository|service|util))+", re.IGNORECASE)
GENERATED_HEADER = re.compile(r"^\s*(?://+|#+|/\*+|\*+)\s*(?:@generated\b|code generated\b.*\bdo not edit\b|generated by\b.*\bdo not edit\b|this file (?:is|was) generated\b)", re.IGNORECASE)
